/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class PkkeChallengeUnitTest {

  @Test
  @DisplayName("null challenge returns null")
  void test_from_request_null_challenge() {
    Assertions.assertNull(PkceChallenge.fromRequest(null, "S256"));
    Assertions.assertNull(PkceChallenge.fromRequest(null, "plain"));
    Assertions.assertNull(PkceChallenge.fromRequest(null, null));
  }

  @Test
  @DisplayName("unsupported method throws IllegalArgumentException")
  void test_from_request_unsupported_method() {
    Assertions.assertThrows(IllegalArgumentException.class,
        () -> PkceChallenge.fromRequest("challenge", "unknown"));
    Assertions.assertThrows(IllegalArgumentException.class,
        () -> PkceChallenge.fromRequest("challenge", "SHA256"));
  }

  @Test
  @DisplayName("null method defaults to plain")
  void test_from_request_null_method_defaults_to_plain() {
    PkceChallenge challenge = PkceChallenge.fromRequest("my-verifier", null);
    Assertions.assertEquals("plain", challenge.getMethod());
    Assertions.assertTrue(challenge.verify("my-verifier"));
  }

  @Test
  @DisplayName("plain method verifies exact match")
  void test_plain_verify() {
    PkceChallenge challenge = PkceChallenge.fromRequest("secret-verifier", "plain");
    Assertions.assertEquals("plain", challenge.getMethod());
    Assertions.assertEquals("secret-verifier", challenge.getChallenge());
    Assertions.assertTrue(challenge.verify("secret-verifier"));
    Assertions.assertFalse(challenge.verify("wrong-verifier"));
    Assertions.assertFalse(challenge.verify(""));
  }

  @Test
  @DisplayName("S256 verify using RFC 7636 Appendix B test vector")
  void test_s256_verify() {
    String verifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";
    String expectedChallenge = "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM";

    PkceChallenge challenge = PkceChallenge.fromRequest(expectedChallenge, "S256");
    Assertions.assertEquals("S256", challenge.getMethod());
    Assertions.assertEquals(expectedChallenge, challenge.getChallenge());
    Assertions.assertTrue(challenge.verify(verifier));
    Assertions.assertFalse(challenge.verify("wrong-verifier"));
    Assertions.assertFalse(challenge.verify(expectedChallenge));
  }
}
